<?php
declare(strict_types=1);
require_once __DIR__.'/../app/helpers/auth.php';require_once __DIR__.'/../app/config/database.php';require_once __DIR__.'/../app/helpers/gyd_retiros_directos.php';
requireLogin();$u=currentUser()?:[];$uid=(int)($u['id']??0);if(!$uid||!gr_admin($u)){http_response_code(403);exit('Verificación de bóveda exclusiva de Administración/Dirección.');}
$error='';$msg='';$rows=[];
try {
 $db=(new Database())->connect();gr_test_db($db);
 if($_SERVER['REQUEST_METHOD']==='POST'){
  gr_post_guard();$id=(int)($_POST['id']??0);$rec=gd_cents($_POST['recibido']??'');$nota=trim((string)($_POST['nota']??''));if($id<1||mb_strlen($nota)>255)throw new DomainException('Datos de verificación inválidos.');
  $db->beginTransaction();
  try {
   $r=gr_query($db,'SELECT * FROM gyd_retiros_boveda WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);
   if(!$r||$r['boveda_estado']!=='SIN_VERIFICAR')throw new DomainException('Retiro inexistente o ya verificado; no se permite sobrescribir la verificación.');
   $original=gd_cents($r['importe']);$estado=$rec===$original?'VERIFICADO':'DIFERENCIA';
   gr_query($db,'UPDATE gyd_retiros_boveda SET boveda_estado=?,verificado_por=?,importe_boveda=?,verificado_en=NOW(),nota_boveda=? WHERE id=?',[$estado,$uid,gd_dollars($rec),$nota?:null,$id]);
   gr_audit($db,$uid,'BOVEDA_VERIFICACION_RETIRO',['retiro'=>gd_folio($id),'importe_ticket'=>gd_dollars($original),'importe_boveda'=>gd_dollars($rec),'diferencia'=>gd_dollars($rec-$original)]);
   $db->commit();$_SESSION['gyd_boveda_flash']='Verificación registrada: '.gd_folio($id).' · '.$estado.'. No se modificó la caja.';
   header('Location: erp_boveda_verificacion.php',true,303);exit;
  }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
 }
 $msg=(string)($_SESSION['gyd_boveda_flash']??'');unset($_SESSION['gyd_boveda_flash']);
 $rows=gr_query($db,"SELECT b.*,s.nombre sucursal,c.nombre caja,u.nombre cajero FROM gyd_retiros_boveda b JOIN pos_cajas c ON c.id=b.caja_id JOIN pos_sucursales s ON s.id=c.sucursal_id LEFT JOIN usuarios u ON u.id=b.cajero_id ORDER BY (b.boveda_estado='SIN_VERIFICAR') DESC,b.id DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){$error=$e instanceof DomainException?$e->getMessage():'Error de consulta. Revisa tablas instaladas.';error_log('G&D verificación bóveda: '.$e->getMessage());}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>G&D | Verificar bóveda</title><style>body{margin:0;background:#f0f4f9;color:#16385a;font:14px system-ui}header{background:#154b7b;padding:20px;color:white}header a{color:white}main{max-width:1250px;margin:22px auto;padding:0 12px}.card{background:white;border:1px solid #d9e5f0;border-radius:12px;padding:20px;margin:12px 0}table{border-collapse:collapse;width:100%;min-width:980px}td,th{padding:9px;border-bottom:1px solid #dfe8f0;text-align:left}th{background:#16568e;color:white}.scroll{overflow:auto}input{font:inherit;padding:9px;border:1px solid #abc0d3;border-radius:7px;max-width:135px}button{padding:9px;border:0;background:#175c9c;color:white;border-radius:7px;cursor:pointer}.warn{background:#fff4df;padding:12px}.good{background:#e4f5e7;padding:12px}.error{background:#ffe4e7;padding:12px}</style></head><body><header><h1>Verificación de dinero recibido en bóveda</h1><a href="erp_cortes_boveda.php">Cortes diarios y retiros</a></header><main><div class="card warn">Los cajeros retiran efectivo sin autorización previa. Esta pantalla <b>solo coteja físicamente</b> los comprobantes con el dinero recibido en bóveda. Una diferencia queda registrada; nunca cambia el monto original del retiro ni el efectivo del corte.</div><?php if($error):?><p class="error"><?=gr_h($error)?></p><?php endif;?><?php if($msg):?><p class="good"><?=gr_h($msg)?></p><?php endif;?><div class="card scroll"><table><thead><tr><th>Folio / hora</th><th>Sucursal / caja</th><th>Cajero</th><th>Importe ticket</th><th>Estado</th><th>Contar y verificar</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="pos_retiro_ticket.php?id=<?=(int)$r['id']?>"><?=gr_h(gd_folio((int)$r['id']))?></a><br><?=gr_h($r['creado_en'])?></td><td><?=gr_h($r['sucursal'])?><br><?=gr_h($r['caja'])?></td><td><?=gr_h($r['cajero']??'')?></td><td><?=gr_money(gd_cents($r['importe']))?></td><td><?=gr_h($r['boveda_estado'])?></td><td><?php if($r['boveda_estado']==='SIN_VERIFICAR'):?><form method="post" onsubmit="return confirm('Registrar cantidad que REALMENTE recibió bóveda, sin cambiar el retiro?')"><input type="hidden" name="csrf" value="<?=gr_h(gr_csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input name="recibido" required placeholder="Recibido $" pattern="[0-9]+(\.[0-9]{1,2})?"><input name="nota" maxlength="255" placeholder="Nota opcional"><button>Verificar recepción</button></form><?php else:?>Recibido: <?=gr_money(gd_cents($r['importe_boveda']))?><br>Fecha: <?=gr_h($r['verificado_en'])?><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No hay retiros nuevos.</td></tr><?php endif;?></tbody></table></div></main></body></html>
